def score(value):
    """Branchy version: many decision points."""
    total = 0
    for item in value:
        if item > 10:
            total += 1
        elif item > 5:
            total += 2
        elif item > 3:
            total += 3
        elif item > 2:
            total += 4
        elif item > 1:
            total += 5
        else:
            total -= 1
        while total > 100:
            total -= 10
            if total % 3 == 0:
                break
        try:
            total += int(item)
        except (TypeError, ValueError):
            total -= 1
    return total if total else -1
